// Static local embedded templates for KTA (no external link / zero network dependency)
export const LOCAL_KTA_FRONT_BASE64 = "data:image/jpeg;base64,";
export const LOCAL_KTA_BACK_BASE64 = "data:image/jpeg;base64,";

export const DEFAULT_LOCAL_KTA_FRONT = "/depan.png";
export const DEFAULT_LOCAL_KTA_BACK = "/Belakang.jpg";

export function getSafeKtaFront(customUrl?: string | null): string {
  if (!customUrl || typeof customUrl !== "string") return DEFAULT_LOCAL_KTA_FRONT;
  const clean = customUrl.trim();
  // If it is an old broken external URL or empty, fallback to local
  if (
    !clean || 
    clean.includes("1OsI7x7zw") || 
    clean.includes("1yeEeoE") || 
    clean.includes("hwjateng.com") || 
    clean.includes("design_card") ||
    clean.startsWith("http://")
  ) {
    return DEFAULT_LOCAL_KTA_FRONT;
  }
  return clean;
}

export function getSafeKtaBack(customUrl?: string | null): string {
  if (!customUrl || typeof customUrl !== "string") return DEFAULT_LOCAL_KTA_BACK;
  const clean = customUrl.trim();
  if (
    !clean || 
    clean.includes("1yeEeoE") || 
    clean.includes("1OsI7x7zw") || 
    clean.includes("hwjateng.com") || 
    clean.includes("design_card") ||
    clean.startsWith("http://")
  ) {
    return DEFAULT_LOCAL_KTA_BACK;
  }
  return clean;
}
